// Sample notifications for DeClear.
//
// These are fixed example messages a user can try without pasting their own
// text. Each one also carries a hand-written, deterministic example result
// (see `exampleResult`). These results are NOT generated by any AI model —
// they are fixed examples authored for the demo so the interface can be shown
// end to end. The real Message_Processor service is a later milestone.
//
// The `exampleResult` shape matches the Processing_Result contract from the
// design document: explanation, requiredActions[], importantDates[],
// urgencyLevel ('None' | 'Low' | 'Medium' | 'High'), and uncertaintyIndicators[].

export const URGENCY_LEVELS = ['None', 'Low', 'Medium', 'High']

